WITH volume_metric AS (SELECT mktcode,tgtcode,MAX_BY(volume,bizdate) AS value FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate>=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' WEEK) AND bizdate<=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' DAY) GROUP BY mktcode,tgtcode), turnover_metric AS (SELECT mktcode,tgtcode,MAX_BY(turnover,bizdate) AS value FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate>=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' WEEK) AND bizdate<=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' DAY) GROUP BY mktcode,tgtcode), volume_rank AS (SELECT mktcode,tgtcode,ROW_NUMBER() OVER(ORDER BY value DESC,mktcode,tgtcode) AS r0 FROM volume_metric), turnover_rank AS (SELECT mktcode,tgtcode,ROW_NUMBER() OVER(ORDER BY value DESC,mktcode,tgtcode) AS r1 FROM turnover_metric) SELECT a.mktcode,a.tgtcode,a.bizdate FROM (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14') a JOIN volume_rank v ON v.mktcode=a.mktcode AND v.tgtcode=a.tgtcode JOIN turnover_rank t ON t.mktcode=a.mktcode AND t.tgtcode=a.tgtcode WHERE v.r0/NULLIF(t.r1,0)<=1;
